# ----- agro_backend/app/application/send_otp.py
cat > "agro_backend/app/application/send_otp.py" <<'AGRO_BS_EOF'
"""Use case: issue an OTP challenge for a farmer phone.


Orchestrates: generate code -> store hashed -> send via WhatsApp port.


Throttling policy (lives here in the application layer, not in HTTP):


* At most one ACTIVE (unconsumed, unexpired) challenge per phone at a
  time. A second send while the previous is alive is rejected with
  :class:`OtpThrottledError` - the client should ask the farmer to
  wait for the existing code (or for it to expire).
* At most 5 challenges per phone per 30 minutes. Catches the case
  where a previous challenge has expired but the farmer is hammering
  the button.


Returns the challenge_id only - never the plain code. The code goes
out via WhatsApp (or to the server log in dev mode).
"""


from __future__ import annotations


import uuid
from dataclasses import dataclass
from datetime import UTC, datetime


from app.application.ports.farmer_repo import FarmerRepo
from app.application.ports.otp_repo import OtpRepo
from app.application.ports.whatsapp_sender import WhatsappSender
from app.domain.auth import (
    OtpChallenge,
    OtpTransport,
    generate_otp_code,
    generate_refresh_secret,
    hash_otp_code,
    mask_phone,
    otp_expires_at,
)


# ---------------------------------------------------------------------------
# Errors - the use case raises domain-shaped errors; HTTP layer translates.
# ---------------------------------------------------------------------------




class SendOtpError(Exception):
    """Base class for send_otp problems."""




class UnknownPhoneError(SendOtpError):
    """No farmer registered with this phone number."""




class OtpThrottledError(SendOtpError):
    """Too many OTPs requested too recently."""


    def __init__(self, reason: str) -> None:
        super().__init__(reason)
        self.reason = reason




class WhatsappDeliveryError(SendOtpError):
    """Send was attempted but the provider rejected it."""


    def __init__(self, provider_error: str) -> None:
        super().__init__(provider_error)
        self.provider_error = provider_error




# ---------------------------------------------------------------------------
# Deps + result
# ---------------------------------------------------------------------------




@dataclass(frozen=True, slots=True)
class SendOtpDeps:
    farmer_repo: FarmerRepo
    otp_repo: OtpRepo
    sender: WhatsappSender
    transport: OtpTransport = OtpTransport.WHATSAPP
    template_name: str = "agroguardian_otp_v1"
    code_ttl_seconds: int = 300
    max_attempts_per_code: int = 5
    rate_window_minutes: int = 30
    rate_max_in_window: int = 5




@dataclass(frozen=True, slots=True)
class SendOtpResult:
    """What the use case returns. Plain code is NOT included."""


    challenge_id: uuid.UUID
    expires_at: datetime
    masked_phone: str




# ---------------------------------------------------------------------------
# Use case
# ---------------------------------------------------------------------------




async def execute(*, phone: str, deps: SendOtpDeps) -> SendOtpResult:
    """Send an OTP to ``phone``. ``phone`` must be E.164."""
    now = datetime.now(UTC)


    farmer = await deps.farmer_repo.find_by_phone(phone)
    if farmer is None:
        raise UnknownPhoneError(phone)


    # Throttle 1: no concurrent active challenge.
    active = await deps.otp_repo.find_latest_active(phone)
    if active is not None and active.can_attempt(now):
        raise OtpThrottledError("active_challenge_exists")


    # Throttle 2: rate limit per phone per window.
    recent = await deps.otp_repo.recent_attempts_count(phone, deps.rate_window_minutes)
    if recent >= deps.rate_max_in_window:
        raise OtpThrottledError("rate_limited")


    # Generate + persist.
    code = generate_otp_code()
    salt = generate_refresh_secret(num_bytes=8)
    challenge = OtpChallenge(
        challenge_id=uuid.uuid4(),
        tenant_id=farmer.tenant_id,
        phone=phone,
        code_hash=hash_otp_code(code, salt),
        transport=deps.transport,
        expires_at=otp_expires_at(now, deps.code_ttl_seconds),
        consumed_at=None,
        attempt_count=0,
        max_attempts=deps.max_attempts_per_code,
        created_at=now,
    )
    challenge_id = await deps.otp_repo.create(challenge)


    # Deliver. The log-only sender prints the code; the Meta adapter doesn't.
    result = await deps.sender.send_otp_template(
        phone=phone,
        code=code,
        template_name=deps.template_name,
    )
    if not result.accepted:
        raise WhatsappDeliveryError(result.error_code or "unknown")


    return SendOtpResult(
        challenge_id=challenge_id,
        expires_at=challenge.expires_at,
        masked_phone=mask_phone(phone),
    )




__all__ = [
    "OtpThrottledError",
    "SendOtpDeps",
    "SendOtpError",
    "SendOtpResult",
    "UnknownPhoneError",
    "WhatsappDeliveryError",
    "execute",
]
AGRO_BS_EOF


# ----- agro_backend/app/application/verify_otp.py
cat > "agro_backend/app/application/verify_otp.py" <<'AGRO_BS_EOF'
"""Use case: verify an OTP and mint a token pair.


Steps:
1. Look up the active challenge for this phone.
2. Constant-time compare the supplied code against its hash.
3. On match: mark consumed, mint access token, create refresh session,
   return the TokenPair.
4. On miss: bump attempt_count, raise InvalidOtpError. After
   ``max_attempts`` misses the challenge is locked.
"""


from __future__ import annotations


import uuid
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta


from app.application.ports.auth_session_repo import AuthSessionRepo
from app.application.ports.farmer_repo import FarmerRepo
from app.application.ports.otp_repo import OtpRepo
from app.application.ports.token_issuer import TokenIssuer
from app.domain.auth import (
    AuthRole,
    AuthSession,
    TokenPair,
    generate_refresh_secret,
    hash_refresh_token,
    verify_otp_code,
)


# ---------------------------------------------------------------------------
# Errors
# ---------------------------------------------------------------------------




class VerifyOtpError(Exception):
    pass




class NoActiveChallengeError(VerifyOtpError):
    """No live OTP challenge for this phone (expired or never sent)."""




class ChallengeLockedError(VerifyOtpError):
    """Too many wrong guesses; the challenge is dead."""




class InvalidOtpError(VerifyOtpError):
    """Wrong code. ``attempts_remaining`` is the new count after this miss."""


    def __init__(self, attempts_remaining: int) -> None:
        super().__init__("invalid_otp")
        self.attempts_remaining = attempts_remaining




class FarmerInactiveError(VerifyOtpError):
    """Farmer's account_status is not 'active'."""




# ---------------------------------------------------------------------------
# Deps + result
# ---------------------------------------------------------------------------




@dataclass(frozen=True, slots=True)
class VerifyOtpDeps:
    farmer_repo: FarmerRepo
    otp_repo: OtpRepo
    session_repo: AuthSessionRepo
    token_issuer: TokenIssuer
    refresh_ttl_seconds: int = 30 * 24 * 3600  # 30 days




# ---------------------------------------------------------------------------
# Use case
# ---------------------------------------------------------------------------




async def execute(
    *,
    phone: str,
    code: str,
    deps: VerifyOtpDeps,
    user_agent: str | None = None,
    ip_address: str | None = None,
) -> TokenPair:
    """Verify ``code`` against the active challenge for ``phone``.


    Returns a fresh TokenPair. Caller is responsible for shipping it
    over HTTPS only.
    """
    now = datetime.now(UTC)


    challenge = await deps.otp_repo.find_latest_active(phone)
    if challenge is None or challenge.is_expired(now) or challenge.is_consumed():
        raise NoActiveChallengeError(phone)


    if challenge.is_locked():
        raise ChallengeLockedError(phone)


    if not verify_otp_code(code, challenge.code_hash):
        new_count = await deps.otp_repo.increment_attempt(challenge.challenge_id)
        remaining = max(0, challenge.max_attempts - new_count)
        raise InvalidOtpError(attempts_remaining=remaining)


    # Hit. Lock the challenge so it can't be reused.
    await deps.otp_repo.mark_consumed(challenge.challenge_id)


    farmer = await deps.farmer_repo.find_by_phone(phone)
    if farmer is None or farmer.account_status != "active":
        raise FarmerInactiveError(phone)


    # Mint refresh session FIRST so we can embed its id in the access token.
    refresh_secret = generate_refresh_secret()
    refresh_expires_at = now + timedelta(seconds=deps.refresh_ttl_seconds)
    session = AuthSession(
        session_id=uuid.uuid4(),
        tenant_id=farmer.tenant_id,
        farmer_id=farmer.farmer_id,
        refresh_token_hash=hash_refresh_token(refresh_secret),
        expires_at=refresh_expires_at,
        revoked_at=None,
        created_at=now,
        last_used_at=now,
    )
    session_id = await deps.session_repo.create(session)


    access_token, claims = deps.token_issuer.issue_access_token(
        subject=farmer.farmer_id,
        tenant_id=farmer.tenant_id,
        role=AuthRole.FARMER,
        session_id=session_id,
    )


    return TokenPair(
        access_token=access_token,
        refresh_token=refresh_secret,
        access_expires_at=claims.expires_at,
        refresh_expires_at=refresh_expires_at,
    )




__all__ = [
    "ChallengeLockedError",
    "FarmerInactiveError",
    "InvalidOtpError",
    "NoActiveChallengeError",
    "VerifyOtpDeps",
    "VerifyOtpError",
    "execute",
]
AGRO_BS_EOF


# ----- agro_backend/app/application/refresh_token.py
cat > "agro_backend/app/application/refresh_token.py" <<'AGRO_BS_EOF'
"""Use case: rotate a refresh token, return a fresh access+refresh pair.


Refresh-token rotation policy (lives here, not in HTTP):


1. Client presents a refresh secret. We hash it and look up the session.
2. If the session is missing, revoked, or expired -> reject.
3. Otherwise: mint NEW access + NEW refresh secret. Mark the OLD
   session revoked. Persist the new session. Return the pair.


Rotation on every refresh is the OWASP recommendation and the simplest
detection for refresh-token theft (the legitimate client and the
attacker will both eventually present the same revoked token; the
second one sees a 401 and we know something's wrong).
"""


from __future__ import annotations


import uuid
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta


from app.application.ports.auth_session_repo import AuthSessionRepo
from app.application.ports.farmer_repo import FarmerRepo
from app.application.ports.token_issuer import TokenIssuer
from app.domain.auth import (
    AuthRole,
    AuthSession,
    TokenPair,
    generate_refresh_secret,
    hash_refresh_token,
)




class RefreshError(Exception):
    pass




class InvalidRefreshTokenError(RefreshError):
    """Token is unknown, revoked, or expired."""




@dataclass(frozen=True, slots=True)
class RefreshTokenDeps:
    farmer_repo: FarmerRepo
    session_repo: AuthSessionRepo
    token_issuer: TokenIssuer
    refresh_ttl_seconds: int = 30 * 24 * 3600




async def execute(*, refresh_secret: str, deps: RefreshTokenDeps) -> TokenPair:
    """Rotate the refresh token. Returns a fresh TokenPair."""
    now = datetime.now(UTC)
    token_hash = hash_refresh_token(refresh_secret)


    old = await deps.session_repo.find_by_token_hash(token_hash)
    if old is None or not old.is_active(now):
        raise InvalidRefreshTokenError()


    farmer = await deps.farmer_repo.find_by_id(old.farmer_id)
    if farmer is None or farmer.account_status != "active":
        # Revoke the dangling session so future calls don't keep trying.
        await deps.session_repo.revoke(old.session_id)
        raise InvalidRefreshTokenError()


    # Mint a NEW refresh secret + session, revoke the old.
    new_secret = generate_refresh_secret()
    new_expires_at = now + timedelta(seconds=deps.refresh_ttl_seconds)
    new_session = AuthSession(
        session_id=uuid.uuid4(),
        tenant_id=old.tenant_id,
        farmer_id=old.farmer_id,
        refresh_token_hash=hash_refresh_token(new_secret),
        expires_at=new_expires_at,
        revoked_at=None,
        created_at=now,
        last_used_at=now,
    )
    new_session_id = await deps.session_repo.create(new_session)
    await deps.session_repo.revoke(old.session_id)


    access_token, claims = deps.token_issuer.issue_access_token(
        subject=farmer.farmer_id,
        tenant_id=farmer.tenant_id,
        role=AuthRole.FARMER,
        session_id=new_session_id,
    )


    return TokenPair(
        access_token=access_token,
        refresh_token=new_secret,
        access_expires_at=claims.expires_at,
        refresh_expires_at=new_expires_at,
    )




__all__ = ["InvalidRefreshTokenError", "RefreshError", "RefreshTokenDeps", "execute"]
AGRO_BS_EOF


