"""Tests for app.domain.auth - all pure, no IO, no fixtures needed."""


from __future__ import annotations


import random
import uuid
from datetime import UTC, datetime, timedelta


import pytest


from app.domain.auth import (
    OTP_CODE_LENGTH,
    AccessClaims,
    AuthRole,
    AuthSession,
    OtpChallenge,
    OtpTransport,
    TokenPair,
    generate_otp_code,
