def test_auth_session_is_active_when_unrevoked_and_unexpired() -> None:
    s = AuthSession(
        session_id=uuid.uuid4(),
        tenant_id=uuid.uuid4(),
        farmer_id=uuid.uuid4(),
        refresh_token_hash="h",
